function isDependencyStatus(value: unknown): value is DependencyStatus {
  if (value === null || typeof value !== 'object') return false
  const status = value as Record<string, unknown>
  return MANAGED_DEPENDENCIES.some(dependency => dependency.id === status.id)
    && typeof status.packageName === 'string' && typeof status.installed === 'boolean' && typeof status.updateAvailable === 'boolean'
}

export function isInstallProgress(value: unknown): value is InstallProgress {
  if (value === null || typeof value !== 'object') return false
  const progress = value as Record<string, unknown>
  const phase = progress.phase
  const total = progress.total
  const percent = progress.percent
  const currentPackage = progress.currentPackage
  return typeof progress.active === 'boolean'
    && typeof progress.target === 'string'
    && typeof progress.seconds === 'number' && Number.isInteger(progress.seconds) && progress.seconds >= 0
    && typeof progress.lastLine === 'string'
    && (phase === null || (typeof phase === 'string' && PROGRESS_PHASES.has(phase as ProgressPhase)))
    && typeof progress.done === 'number' && Number.isInteger(progress.done) && progress.done >= 0
    && (total === null || (typeof total === 'number' && Number.isInteger(total) && total >= 0))
    && (percent === null || (typeof percent === 'number' && Number.isFinite(percent) && percent >= 0 && percent <= 100))
    && (currentPackage === null || typeof currentPackage === 'string')
}

function progressLabel(progress: InstallProgress, t: TranslateNS<typeof NS>): string {
  if (progress.phase !== null) {
    const current = progress.currentPackage === null || progress.currentPackage === '' ? '' : ` · ${progress.currentPackage}`
    const done = progress.done > 0 ? ` · ${t('about.packagesDone').replace('{0}', String(progress.done))}` : ''
    return `${t(`about.progress.${progress.phase}`)}${current}${done}`
  }
  if (progress.lastLine !== '') return `${progress.lastLine}  (${progress.seconds}s)`
  return t('about.progressHint')
}

/** Workspace UI 的功能说明、配套管理插件状态与受限安装入口。 */
export function AboutSection(props: { t: TranslateNS<typeof NS>; close?: () => void }) {
  const { t } = props
  const ctx = getClientContext()
  const [dependencies, setDependencies] = useState<readonly DependencyStatus[]>([])
  const [state, setState] = useState<LoadState>('loading')
  const [installing, setInstalling] = useState<InstallTarget>()
  const [progress, setProgress] = useState<InstallProgress>()
  const [message, setMessage] = useState<{ error: boolean; text: string }>()
  const [refreshFailed, setRefreshFailed] = useState(false)
  const [loadFailure, setLoadFailure] = useState<unknown>()
  const alive = useRef(true)
  const root = useRef<HTMLElement>(null)
  const stateRef = useRef<LoadState>('loading')
  const requestId = useRef(0)
  const installingRef = useRef<InstallTarget>()
  stateRef.current = state
  useEffect(() => { alive.current = true; return () => { alive.current = false } }, [])
  const load = useCallback(async (signal?: AbortSignal) => {
    const currentRequest = ++requestId.current
    if (stateRef.current !== 'ready') setState('loading')
    try {
      const response = await fetch(endpoint, { cache: 'no-store', signal })
      if (!response.ok) throw new BusinessRequestError(response.status)
      const payload = await response.json() as { dependencies?: unknown }
      if (signal?.aborted || currentRequest !== requestId.current) return
      if (!Array.isArray(payload.dependencies) || !payload.dependencies.every(isDependencyStatus)) throw new Error()
      setDependencies(payload.dependencies)
      setState('ready')
      setRefreshFailed(false)
      setLoadFailure(undefined)
    } catch (error) {
      if (signal?.aborted || (error instanceof DOMException && error.name === 'AbortError') || currentRequest !== requestId.current) return
      setLoadFailure(error)
      if (stateRef.current === 'ready') setRefreshFailed(true)
      else setState('failed')
    }
  }, [])
  useEffect(() => {
    const node = root.current
    const controller = new AbortController()
    const refresh = (): void => { void load(controller.signal) }
    refresh()
    if (node === null || typeof IntersectionObserver === 'undefined') {
      return () => { controller.abort() }
    }
    let initialized = false
    let wasVisible = false
    const observer = new IntersectionObserver((entries) => {
      const visible = entries.some((entry) => entry.isIntersecting)
      if (!initialized) { initialized = true; wasVisible = visible; return }
      if (visible && !wasVisible) refresh()
      wasVisible = visible
    }, { threshold: 0.2 })
    observer.observe(node)
    return () => {
      controller.abort()
      observer.disconnect()
    }
  }, [load])
  useEffect(() => {
    if (installing === undefined) {
      setProgress(undefined)
      return
    }
    let cancelled = false
    const pull = async (): Promise<void> => {
      try {
        const response = await fetch(`${endpoint}?action=progress`, { cache: 'no-store' })
        const payload = await response.json() as { progress?: unknown }
        if (cancelled || !response.ok || !isInstallProgress(payload.progress)) return
        setProgress(payload.progress)
      } catch {
        // 轮询失败时忽略异常
      }
    }
    void pull()
    const timer = window.setInterval(() => { void pull() }, 800)
    return () => {
      cancelled = true
      window.clearInterval(timer)
    }
  }, [installing])
  useEffect(() => {
    try {
      const remote = (ctx as any)?.remote
      if (typeof remote?.$on !== 'function') return
      const unsubs: Array<(() => void) | undefined> = []
      try {
        unsubs.push(remote.$on('plugin-manager/install-state', (data: any) => {
          if (data?.phase && typeof data.phase === 'string') {
            setProgress(prev => prev ? { ...prev, phase: data.phase } : undefined)
          }
        }))
      } catch {
        // ignore
      }
      try {
        unsubs.push(remote.$on('plugin-manager/changed', () => {
          void load()
        }))
      } catch {
        // ignore
      }
      return () => {
        unsubs.forEach(unsub => { try { unsub?.() } catch {} })
      }
    } catch {
      // ignore
    }
  }, [ctx, load])

  const install = async (id: ManagedDependencyId): Promise<void> => {
    if (installingRef.current !== undefined) return
    const dependency = dependencies.find(dep => dep.id === id)
    if (dependency === undefined) return
    installingRef.current = id
    setInstalling(id)
    setMessage(undefined)
    try {
      const response = await fetch(`${endpoint}?dependency=${encodeURIComponent(id)}`, { method: 'POST' })
      let payload: { dependencies?: unknown; error?: unknown; application?: unknown } = {}
      try {
        payload = await response.json() as { dependencies?: unknown; error?: unknown; application?: unknown }
      } catch {
        // ignore
      }
      if ([401, 403].includes(response.status)) throw new BusinessRequestError(response.status)
      if (Array.isArray(payload.dependencies) && payload.dependencies.every(isDependencyStatus) && alive.current) {
        setDependencies(payload.dependencies)
      }
      if (!response.ok || !Array.isArray(payload.dependencies) || !payload.dependencies.every(isDependencyStatus) || (payload.application !== 'applied' && payload.application !== 'restart-required' && payload.application !== 'overridden')) {
        throw new Error(typeof payload.error === 'string' ? payload.error : t('about.installFailed'))
      }
      if (!alive.current) return
      setState('ready')
      setRefreshFailed(false)
      setMessage({ error: false, text: payload.application === 'overridden' ? t('about.applied') : (payload.application === 'applied' ? t('about.applied') : t('about.restartRequired')) })
    } catch (error) {
      if (!alive.current) return
      setMessage({ error: true, text: installErrorText(error, t) })
    } finally {
      installingRef.current = undefined
      if (alive.current) setInstalling(undefined)
    }
  }
  const updateAll = async (): Promise<void> => {
    if (installingRef.current !== undefined) return
    installingRef.current = 'all'
    setInstalling('all')
    setMessage(undefined)
    try {
      const response = await fetch(`${endpoint}?action=update-all`, { method: 'POST' })
      let payload: { dependencies?: unknown; error?: unknown; application?: unknown; updatedCount?: unknown; results?: unknown } = {}
      try {
        payload = await response.json() as { dependencies?: unknown; error?: unknown; application?: unknown; updatedCount?: unknown; results?: unknown }
      } catch {
        // ignore
      }
      if ([401, 403].includes(response.status)) throw new BusinessRequestError(response.status)
      if (Array.isArray(payload.dependencies) && payload.dependencies.every(isDependencyStatus) && alive.current) {
        setDependencies(payload.dependencies)
      }
      if (!response.ok || !Array.isArray(payload.dependencies) || !payload.dependencies.every(isDependencyStatus) || (payload.application !== 'applied' && payload.application !== 'restart-required' && payload.application !== 'overridden')) {
        throw new Error(typeof payload.error === 'string' ? payload.error : t('about.installFailed'))
      }
      if (!alive.current) return
      setState('ready')
      setRefreshFailed(false)
      setMessage({ error: false, text: (payload.application === 'applied' || payload.application === 'overridden') && payload.updatedCount === 0 && Array.isArray(payload.results) && payload.results.length === 0
        ? t('about.upToDate')
        : (payload.application === 'overridden' ? t('about.applied') : (payload.application === 'applied' ? t('about.applied') : t('about.restartRequired'))) })
    } catch (error) {
      if (!alive.current) return
      setMessage({ error: true, text: installErrorText(error, t) })
    } finally {
      installingRef.current = undefined
      if (alive.current) setInstalling(undefined)
    }
  }
  const actionableCount = dependencies.filter(dependency => !dependency.installed || dependency.updateAvailable).length
  const title = (id: ManagedDependencyId): string => t(`about.dependency.${id}`)
  return <section ref={root} className="wui-about" aria-label={t('about.nav')}>
    <style>{stylesheet}</style>
    {/* 区域一：内置功能与子插件介绍卡片 */}
    <div className="wui-section-card wui-card-features">
      <div className="wui-about-head">
        <div className="wui-about-title-row">
          <h2 className="wui-about-title">{t('about.title')}</h2>
          <div className="wui-about-feedback-links wui-about-links">
            <PrimitiveButton
              variant="outline"
              size="sm"
              icon={<GithubMark16 />}
              aria-label={t('about.viewProject')}
              onClick={() => { openExternal(PROJECT_URL) }}
            >
              {t('about.viewProject')}
            </PrimitiveButton>
            <PrimitiveButton
              variant="outline"
              size="sm"
              icon={<IconListPenOutlineMedium size={14} />}
              aria-label={t('about.feedback')}
              onClick={() => { openExternal(`${PROJECT_URL}/issues`) }}
            >
              {t('about.feedback')}
            </PrimitiveButton>
          </div>
        </div>
        <p className="wui-about-desc">{t('about.description')}</p>
      </div>
      <div className="wui-section-subtitle-wrap">
        <span className="wui-section-subtitle">
          {t('about.features')}
        </span>
      </div>
      <div className="wui-subplugins-list">
        {SUB_PLUGINS.map(item => (
          <div key={item.id} className="wui-subplugin-item">
            <div className="wui-subplugin-header">
              <span className="wui-subplugin-name">{t(item.nameKey)}</span>
              <code className="wui-subplugin-badge">{item.id}</code>
            </div>
            <p className="wui-subplugin-desc">{t(item.descKey)}</p>
          </div>
        ))}
      </div>
    </div>

    {/* 区域二：界面外观与换肤配置卡片 */}
    <ThemeSettingsCard t={t} />

    {/* 区域二之一：输入框增强开关 */}
    <ComposerSettingsCard t={t} />

    {/* 区域三：配套生态管理与在线更新卡片 */}
    <div className="wui-section-card wui-card-dependencies">
      <div className="wui-section-header">
        <div className="wui-section-title-wrap">
          <h3 className="wui-section-title">{t('about.dependencies')}</h3>
          <p className="wui-section-desc">{t('about.dependenciesDescription')}</p>
        </div>
        {state === 'ready' && actionableCount > 0 && <PrimitiveButton variant="outline" size="sm" icon={installing === 'all' ? <IconLoadingOutlineMedium size={14} /> : <IconDownloadOutlineMedium size={14} />} aria-busy={installing === 'all'} disabled={installing !== undefined} onClick={() => { void updateAll() }}>{installing === 'all' ? t('about.updatingAll') : t('about.updateAll')}</PrimitiveButton>}
      </div>
    {state === 'loading' ? <div className="wui-about-message" role="status">{t('about.loading')}</div>
      : state === 'failed' ? <div className="wui-about-message" data-error="true" role="alert">{t(businessRequestErrorKey(loadFailure) ?? 'about.statusFailed')}</div>
        : <div className="wui-about-dependencies" aria-busy={installing !== undefined}>{dependencies.map(dependency => <article className="wui-about-dependency" key={dependency.id} data-dependency-id={dependency.id}><div className="wui-about-copy"><div className="wui-about-name-row"><a className="wui-about-name wui-about-project-link" href={PROJECT_HOMEPAGES[dependency.id]} target="_blank" rel="noreferrer">{title(dependency.id)}</a><a className="wui-about-downloads" href={`https://www.npmjs.com/package/${dependency.packageName}`} target="_blank" rel="noreferrer" title={t('about.downloadsSource')} aria-label={`${dependency.packageName} · ${t('about.totalDownloads')} · ${typeof dependency.totalDownloads === 'number' && Number.isSafeInteger(dependency.totalDownloads) && dependency.totalDownloads >= 0 ? dependency.totalDownloads.toLocaleString() : t('about.downloadsUnavailable')}`}><IconDownloadOutlineMedium size={12} aria-hidden="true" /><span className="wui-about-downloads-count">{typeof dependency.totalDownloads === 'number' && Number.isSafeInteger(dependency.totalDownloads) && dependency.totalDownloads >= 0 ? dependency.totalDownloads.toLocaleString() : '—'}</span></a></div><div className="wui-about-package" title={dependency.packageName}><a className="wui-about-project-link" href={PROJECT_HOMEPAGES[dependency.id]} target="_blank" rel="noreferrer">{dependency.packageName}</a>{dependency.version === undefined ? '' : ` · ${dependency.version}`}{dependency.updateAvailable && dependency.latestVersion !== undefined ? ` → ${dependency.latestVersion}` : ''}</div></div><div className="wui-about-actions"><div className="wui-about-status" data-installed={dependency.installed} data-update={dependency.updateAvailable}>{dependency.installed && !dependency.updateAvailable && <IconCheckOutlineMedium size={14} />}{dependency.updateAvailable ? t('about.updateAvailable') : dependency.installed ? t('about.installed') : t('about.missing')}</div>{(!dependency.installed || dependency.updateAvailable) && <PrimitiveButton variant="outline" size="sm" icon={installing === dependency.id ? <IconLoadingOutlineMedium size={14} /> : (!dependency.installed ? <IconDownloadOutlineMedium size={14} /> : <IconRefreshOutlineMedium size={14} />)} disabled={installing !== undefined} aria-busy={installing === dependency.id} onClick={() => { void install(dependency.id) }}>{installing === dependency.id ? t('about.installing') : dependency.updateAvailable ? t('about.update') : t('about.install')}</PrimitiveButton>}</div></article>)}</div>}
    {installing !== undefined && <div className="wui-about-progress" role="status"><span><IconLoadingOutlineMedium size={14} /></span><code>{progress === undefined ? t('about.progressHint') : progressLabel(progress, t)}</code>{progress?.percent !== null && progress?.percent !== undefined && <span className="wui-about-progress-pct">{progress.percent}%</span>}<div className="wui-about-progress-bar"><div className="wui-about-progress-fill" data-wave={progress?.percent === null || progress?.percent === undefined} style={progress?.percent === null || progress?.percent === undefined ? undefined : { width: `${progress.percent}%` }} /></div></div>}
    {refreshFailed && state === 'ready' && <div className="wui-about-message" data-error="true" role="status">{t(businessRequestErrorKey(loadFailure) ?? 'about.refreshFailed')}</div>}
    {message !== undefined && <div className="wui-about-message" data-error={message.error} role={message.error ? 'alert' : 'status'}>{message.text}</div>}
    </div>
  </section>
}
