let lastSkinCheckTime = 0
let cachedSkinEnabledResult: boolean | null = null

/** 探测宿主 settings-skin 子组件是否处于激活状态（含 5 秒 TTL 缓存，避免频繁打开弹层连续网络开销） */
export async function checkSettingsSkinEnabled(force = false): Promise<boolean> {
  const now = Date.now()
  if (!force && cachedSkinEnabledResult !== null && now - lastSkinCheckTime < 5000) {
    return cachedSkinEnabledResult
  }
  try {
    const response = await fetch(WORKSPACE_UI_API_ENDPOINTS.settingsSkin, {
      headers: { Accept: 'application/json' },
      cache: 'no-store',
    })
    if (!response.ok) {
      cachedSkinEnabledResult = false
      lastSkinCheckTime = now
      return false
    }
    const data = await response.json()
    cachedSkinEnabledResult = data?.enabled === true
    lastSkinCheckTime = now
    return cachedSkinEnabledResult
  } catch {
    // 无法连通 settings-skin 端点（例如子组件被停用导致端点不存在、或网络断开），坚决返回 false！
    cachedSkinEnabledResult = false
    lastSkinCheckTime = now
    return false
  }
}

/** 重置 settings-skin 探测缓存（用于测试或强制重新探测） */
export function refreshSettingsSkinCache(): void {
  lastSkinCheckTime = 0
  cachedSkinEnabledResult = null
}

/** 注入 Codex 1:1 设置皮肤样式 */
export function installSettingsSkin(doc: Document = document): () => void {
  const existing = doc.getElementById(SETTINGS_SKIN_STYLE_ID)
  if (existing !== null) {
    // 若已存在但样式内容有变动，热更新其 textContent，绝不锁死旧样式
    if (existing.textContent !== SETTINGS_SKIN_CSS) {
      existing.textContent = SETTINGS_SKIN_CSS
    }
    return () => { existing.remove() }
  }
  const style = doc.createElement('style')
  style.id = SETTINGS_SKIN_STYLE_ID
  style.textContent = SETTINGS_SKIN_CSS
  ;(doc.head ?? doc.documentElement).appendChild(style)
  return () => { if (style.parentNode !== null) style.remove() }
}

/** 彻底卸载 Codex 设置皮肤并清理 DOM 样式节点 */
export function uninstallSettingsSkin(doc: Document = document): void {
  const existing = doc.getElementById(SETTINGS_SKIN_STYLE_ID)
  if (existing !== null) {
    existing.remove()
  }
}

/** 宿主官方侧栏标准默认展开宽度为 280px，可拖拽下限为 264px */
export const DEFAULT_SIDEBAR_WIDTH = 280
export const MIN_SIDEBAR_WIDTH = 264

/**
 * 探测宿主首页主侧栏的展开宽度（默认 280px，最小 264px）
 * 1. 优先解析 AppFrame 上的 gridTemplateColumns（如 280px minmax(...) ...）；
 * 2. 其次读取宿主 Windows 标题栏或侧栏 CSS 变量；
 * 3. 再次直接测量宿主侧栏 DOM 容器元素的实际宽度；
 * 4. 若侧栏处于折叠状态（56px / 0px）或未找到，则安全回退至宿主官方标准默认宽度 280px。
 */
export function getHostSidebarExpandedWidth(doc: Document = document): number {
  if (!doc) return DEFAULT_SIDEBAR_WIDTH

  // 1. 尝试从 AppFrame 元素行内 gridTemplateColumns 解析
  try {
    for (const node of doc.querySelectorAll<HTMLElement>('div')) {
      const grid = node.style?.gridTemplateColumns
      if (grid && grid.includes('minmax')) {
        const match = /^(\d+(?:\.\d+)?)px\s+/.exec(grid.trim())
        if (match) {
          const parsed = Number(match[1])
          if (Number.isFinite(parsed) && parsed >= MIN_SIDEBAR_WIDTH) {
            return parsed
          }
        }
      }
    }
  } catch {
    // 忽略异常
  }

  // 2. 尝试从宿主 CSS 变量读取
  try {
    const rootStyle = doc.documentElement ? getComputedStyle(doc.documentElement) : null
    if (rootStyle) {
      const winWidth = Number.parseFloat(rootStyle.getPropertyValue('--dsh-windows-sidebar-width'))
      if (Number.isFinite(winWidth) && winWidth >= MIN_SIDEBAR_WIDTH) return winWidth
      const hostWidth = Number.parseFloat(rootStyle.getPropertyValue('--dsh-sidebar-width'))
      if (Number.isFinite(hostWidth) && hostWidth >= MIN_SIDEBAR_WIDTH) return hostWidth
    }
  } catch {
    // 忽略异常
  }

  // 3. 尝试直接测量 DOM 侧栏容器
  try {
    const sidebarEl = doc.querySelector<HTMLElement>('[data-slot="sidebar"]')
      ?? doc.querySelector<HTMLElement>('div[class*="sidebarCol"]')
      ?? doc.querySelector<HTMLElement>('div[class*="hHd-Xa_root"]')
    if (sidebarEl) {
      const measured = sidebarEl.getBoundingClientRect?.().width
      if (typeof measured === 'number' && Number.isFinite(measured) && measured >= MIN_SIDEBAR_WIDTH) {
        return measured
      }
    }
  } catch {
    // 忽略异常
  }

  return DEFAULT_SIDEBAR_WIDTH
}

/** 探测宿主首页侧栏是否处于折叠状态（56px 导轨或窄屏自动收起） */
export function isHostSidebarCollapsed(doc: Document = document): boolean {
  if (!doc) return false
  try {
    if (doc.querySelector('[data-sidebar-collapsed="true"], [data-sidebar-collapsed]') !== null) {
      return true
    }
    const sidebarEl = doc.querySelector<HTMLElement>('[data-slot="sidebar"]')
      ?? doc.querySelector<HTMLElement>('div[class*="sidebarCol"]')
      ?? doc.querySelector<HTMLElement>('div[class*="hHd-Xa_root"]')
    if (sidebarEl) {
      const measured = sidebarEl.getBoundingClientRect?.().width
      if (typeof measured === 'number' && Number.isFinite(measured) && measured > 0 && measured <= 64) {
        return true
      }
    }
  } catch {
    // 忽略
  }
  return false
}

/**
 * 对宿主动态生成的菜单按钮执行无侵入的已知项分组与搜索过滤
 */
export function decorateSettingsNav(panelEl: HTMLElement): () => void {
  // 同步主侧栏展开/收起状态至模态框，确保与首页侧栏严格 1:1 对齐
  const isCollapsed = isHostSidebarCollapsed(panelEl.ownerDocument || document)
  if (isCollapsed) {
    panelEl.setAttribute('data-sidebar-collapsed', 'true')
    panelEl.style.setProperty('--wui-settings-nav-width', '56px')
  } else {
    panelEl.removeAttribute('data-sidebar-collapsed')
    const sidebarWidth = getHostSidebarExpandedWidth(panelEl.ownerDocument || document)
    panelEl.style.setProperty('--wui-settings-nav-width', `${sidebarWidth}px`)
  }

  // 兼容新旧两版宿主结构：新版（0.2.1-alpha.3+）navTitle 与 nav 为同级兄弟节点；旧版 navTitle 是 nav 的首个子元素
  const navHeader = panelEl.querySelector<HTMLElement>(':scope > [class*="navTitle"]')
    ?? panelEl.querySelector<HTMLElement>('nav > :first-child')
  const navList = panelEl.querySelector<HTMLElement>('nav [class*="navList"]')
    ?? panelEl.querySelector<HTMLElement>('nav > :nth-child(2)')
    ?? panelEl.querySelector<HTMLElement>('nav > :first-child')
  if (!navList) return () => {}
  const doc = panelEl.ownerDocument
  const phone = doc.defaultView?.matchMedia?.(MOBILE_SETTINGS_QUERY)
  const hasHorizontalTabs = () => phone?.matches === true
    && doc.documentElement.hasAttribute('data-wui-mobile-web')
    && panelEl.querySelector(':scope > [class*="_options"]') !== null

  const revealActiveTab = () => {
    if (!hasHorizontalTabs() || typeof navList.scrollBy !== 'function') return
    const active = navList.querySelector<HTMLElement>(':scope > button[aria-current="true"], :scope > button[class*="_active"]')
    if (active === null) return
    const listBox = navList.getBoundingClientRect()
    const tabBox = active.getBoundingClientRect()
    const left = tabBox.left - listBox.left
    const right = tabBox.right - listBox.right
    if (left < 0 || right > 0) navList.scrollBy({ left: left < 0 ? left : right })
  }

  const isZh = (document.documentElement.lang || 'zh').startsWith('zh')

  // 1. 装饰顶部 Header（返回箭头 + 搜索框，挂载 React 宿主原生 Input 原语）
  let cleanHeader = () => {}
  if (navHeader && !navHeader.querySelector('.wui-settings-nav-header-root')) {
    const originalChildren = Array.from(navHeader.childNodes)
    originalChildren.forEach(child => {
      if (child instanceof HTMLElement) {
        child.style.display = 'none'
      } else if (child.nodeType === 3) {
        child.textContent = ''
      }
    })

    const headerRoot = document.createElement('div')
    headerRoot.className = 'wui-settings-nav-header-root'

    render(React.createElement(SettingsNavHeader), headerRoot)
    navHeader.appendChild(headerRoot)

    cleanHeader = () => {
      unmountComponentAtNode(headerRoot)
      headerRoot.remove()
      originalChildren.forEach(child => {
        if (child instanceof HTMLElement) child.style.removeProperty('display')
      })
    }
  }

  // 2. 注入三组分组小标题（若不存在）
  for (const group of SETTINGS_NAV_GROUPS) {
    if (!navList.querySelector(`[data-wui-group-header="${group.id}"]`)) {
      const header = document.createElement('div')
      header.className = 'wui-settings-nav-group-header'
      header.setAttribute('data-wui-group-header', group.id)
      header.style.setProperty('order', String(group.order))
      header.textContent = isZh ? group.defaultZh : group.defaultEn
      navList.appendChild(header)
    }
  }

  // 3. 注入空状态提示（若不存在）
  let emptyTip = navList.querySelector<HTMLElement>('[data-wui-group-empty]')
  if (!emptyTip) {
    emptyTip = document.createElement('div')
    emptyTip.className = 'wui-settings-nav-empty'
    emptyTip.setAttribute('data-wui-group-empty', '')
    emptyTip.style.setProperty('order', '999')
    emptyTip.style.display = 'none'
    emptyTip.textContent = isZh ? zh['settings.noResults'] : en['settings.noResults']
    navList.appendChild(emptyTip)
  }

  // 安全提取设置按钮正文文本（兼容老版单 span 与新版 navIcon + navLabel 双 span 结构）
  const getNavButtonLabel = (btn: HTMLButtonElement): string => {
    const labelEl = btn.querySelector<HTMLElement>('[class*="navLabel"]')
    if (labelEl && labelEl.textContent?.trim()) {
      return labelEl.textContent.trim()
    }
    const textSpan = btn.querySelector<HTMLElement>('span:not([class*="navIcon"])')
    if (textSpan && textSpan.textContent?.trim()) {
      return textSpan.textContent.trim()
    }
    const allSpans = btn.querySelectorAll<HTMLElement>('span')
    for (const s of allSpans) {
      if (s.textContent?.trim() && !s.className?.includes('navIcon')) {
        return s.textContent.trim()
      }
    }
    return btn.textContent?.trim() ?? ''
  }

  // 4. 归类并赋 order 给宿主生成的每个 button，纯通用布局
  const classifyButtons = () => {
    const buttons = navList.querySelectorAll<HTMLButtonElement>(':scope > button')
    buttons.forEach((btn, index) => {
      const label = getNavButtonLabel(btn)
      const group = classifySettingsButton(label)
      const baseOrder = group === 'personal' ? 100 : group === 'records' ? 300 : 200
      btn.style.setProperty('order', String(baseOrder + 1 + index))
      btn.setAttribute('data-wui-group', group)
    })
  }
  classifyButtons()

  // 5. 搜索过滤联动与空分组小标题动态自愈隐藏
  const applyFilter = (query: string) => {
    const trimmed = hasHorizontalTabs() ? '' : query.trim().toLowerCase()
    const buttons = navList.querySelectorAll<HTMLButtonElement>(':scope > button')
    let totalVisible = 0

    for (const btn of buttons) {
      const label = getNavButtonLabel(btn).toLowerCase()
      if (trimmed === '') {
        btn.style.removeProperty('display')
        totalVisible += 1
      } else {
        const matches = label.includes(trimmed)
        if (matches) {
          btn.style.removeProperty('display')
          totalVisible += 1
        } else {
          btn.style.setProperty('display', 'none', 'important')
        }
      }
    }

    for (const group of SETTINGS_NAV_GROUPS) {
      const header = navList.querySelector<HTMLElement>(`[data-wui-group-header="${group.id}"]`)
      if (header) {
        const visibleCount = [...navList.querySelectorAll<HTMLButtonElement>(`button[data-wui-group="${group.id}"]`)]
          .filter(b => b.style.display !== 'none').length
        if (visibleCount > 0) {
          header.style.removeProperty('display')
        } else {
          header.style.setProperty('display', 'none', 'important')
        }
      }
    }

    if (emptyTip) {
      emptyTip.style.setProperty('display', totalVisible === 0 ? 'block' : 'none', 'important')
    }
  }

  applyFilter(getNavSearchQuery())
  const unsubSearch = subscribeNavSearch(applyFilter)

  // Keep the active host tab in view when opened externally or via the keyboard.
  const refreshTabLayout = () => {
    applyFilter(getNavSearchQuery())
    revealActiveTab()
  }
  phone?.addEventListener('change', refreshTabLayout)
  revealActiveTab()
  const navObserver = new MutationObserver(records => {
    if (records.some(record => record.type === 'childList' && record.target === navList)) {
      classifyButtons()
      applyFilter(getNavSearchQuery())
    }
    revealActiveTab()
  })
  navObserver.observe(navList, { childList: true, subtree: true, attributes: true, attributeFilter: ['aria-current', 'class'] })

  return () => {
    cleanHeader()
    unsubSearch()
    phone?.removeEventListener('change', refreshTabLayout)
    navObserver.disconnect()
    navList.querySelectorAll('[data-wui-group-header], [data-wui-group-empty]').forEach(el => el.remove())
    navList.querySelectorAll<HTMLButtonElement>(':scope > button').forEach(btn => {
      btn.style.removeProperty('order')
      btn.style.display = ''
      btn.removeAttribute('data-wui-group')
    })
  }
}

/**
 * 观察设置弹层的挂载并与子组件生命周期同步
 * 返回 Disposer，卸载时彻底移除 Observer、装饰器与注入样式
 */
export function observeSettingsSkin(_ctx?: Context): () => void {
  let disposed = false
  let cleanDecorator: (() => void) | undefined

  const sync = async (): Promise<void> => {
    if (disposed) return
    const enabled = await checkSettingsSkinEnabled()
    if (disposed) return
    setSkinEnabledState(enabled)
    if (enabled) {
      installSettingsSkin(document)
      const modal = document.querySelector<HTMLElement>('[data-shortcut-modal="settings"]')
      if (modal) {
        cleanDecorator?.()
        cleanDecorator = decorateSettingsNav(modal)
      }
    } else {
      cleanDecorator?.()
      cleanDecorator = undefined
      uninstallSettingsSkin(document)
    }
  }

  // 1. 启动时异步同步状态（受启用门控保护，停用态绝不预先注入样式或装饰 DOM）
  if (typeof document !== 'undefined') {
    void sync()
  }

  const observer = new MutationObserver(mutations => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (node instanceof HTMLElement) {
          const modal = node.getAttribute('data-shortcut-modal') === 'settings'
            ? node
            : node.querySelector<HTMLElement>('[data-shortcut-modal="settings"]')
          if (modal) {
            // 严格受启用状态门控：仅在已确认启用时才预装并装饰，停用态绝不提前注入样式
            if (cachedSkinEnabledResult === true) {
              installSettingsSkin(document)
              cleanDecorator?.()
              cleanDecorator = decorateSettingsNav(modal)
            }
            void sync()
            return
          }
        }
      }
      for (const node of mutation.removedNodes) {
        if (node instanceof HTMLElement) {
          if (node.getAttribute('data-shortcut-modal') === 'settings' || node.querySelector('[data-shortcut-modal="settings"]')) {
            cleanDecorator?.()
            cleanDecorator = undefined
          }
        }
      }
    }
  })

  observer.observe(document.body, { childList: true, subtree: true })

  return () => {
    disposed = true
    observer.disconnect()
    cleanDecorator?.()
    setSkinEnabledState(false)
    uninstallSettingsSkin(document)
  }
}
