import React, { useSyncExternalStore } from 'react'
import { SegmentedControl } from '@deepseek-ai/dsh-client-ui-primitives'
import { SECTION_CARD_CSS, SETTINGS_ROW_CSS } from '../section-card-styles.ts'
import {
  PredictionMode,
  getPredictionSettingsState,
  setPredictionMode,
  subscribePredictionSettings,
} from './prediction-state.ts'
import {
  HistoryScope,
  getHistoryScope,
  setHistoryScope,
  subscribeHistoryScope,
} from './history-scope.ts'
import { PredictionModelPicker } from './PredictionModelPicker.tsx'

export interface ComposerSettingsCardProps {
  t: (key: any) => string
}

/**
 * 输入框增强设置卡片。
 *
 * 放预测开关与 ↑/↓ 历史召回范围；宽度手柄、建议卡片没有可调项，
 * 用不到就不渲染成灰项，遵循插件「不残留死配置」的既有约定。
 *
 * 站点级关闭（profile `cordis.patch.yml` 里 `config: { prediction: false }`）时，
 * 开关保持可见但置为关闭且禁用，并给出原因提示——比整卡消失更容易排查。
 */
export function ComposerSettingsCard({ t }: ComposerSettingsCardProps): React.JSX.Element | null {
  const state = useSyncExternalStore(subscribePredictionSettings, getPredictionSettingsState, getPredictionSettingsState)
  const historyScope = useSyncExternalStore(subscribeHistoryScope, getHistoryScope, getHistoryScope)

  // 当输入增强子插件在 Host 侧被停用时，遵照规范：设置卡片直接全部隐藏，不渲染任何 DOM（与 ThemeSettingsCard 保持一致）
  if (!state.subPluginEnabled) {
    return null
  }

  const lockedByHost = !state.hostAllowed

  return (
    <div className="wui-section-card wui-composer-settings" aria-label={t('composer.title')}>
      <style>{SECTION_CARD_CSS + SETTINGS_ROW_CSS}</style>
      <div className="wui-section-header">
        <div className="wui-section-title-wrap">
          <h3 className="wui-section-title">{t('composer.title')}</h3>
          <p className="wui-section-desc">{t('composer.desc')}</p>
        </div>
      </div>
      <div className="wui-settings-row">
        <div className="wui-settings-row-label">
          <span className="wui-settings-row-title">{t('composer.prediction')}</span>
          <span className="wui-settings-row-hint">{lockedByHost ? t('composer.predictionLocked') : t('composer.predictionHint')}</span>
        </div>
        <SegmentedControl<PredictionMode>
          id="workspace-ui-composer-prediction-mode"
          label={t('composer.prediction')}
          value={state.mode}
          disabled={lockedByHost}
          options={[
            { value: 'off', label: t('composer.modeOff') },
            { value: 'continue', label: t('composer.modeContinue') },
            { value: 'all', label: t('composer.modeAll') },
          ]}
          onChange={(nextMode) => {
            if (lockedByHost) return
            setPredictionMode(nextMode)
          }}
        />
      </div>
      <div className="wui-settings-row">
        <div className="wui-settings-row-label">
          <span className="wui-settings-row-title">{t('composer.predictionModel')}</span>
          <span className="wui-settings-row-hint">{t('composer.predictionModelHint')}</span>
        </div>
        <PredictionModelPicker t={t} disabled={lockedByHost || state.mode === 'off'} />
      </div>
      <div className="wui-settings-row">
        <div className="wui-settings-row-label">
          <span className="wui-settings-row-title">{t('composer.historyScope')}</span>
          <span className="wui-settings-row-hint">{t('composer.historyScopeHint')}</span>
        </div>
        <SegmentedControl<HistoryScope>
          id="workspace-ui-composer-history-scope"
          label={t('composer.historyScope')}
          value={historyScope}
          options={[
            { value: 'session', label: t('composer.historyScopeSession') },
            { value: 'workspace', label: t('composer.historyScopeWorkspace') },
          ]}
          onChange={(nextScope) => { setHistoryScope(nextScope) }}
        />
      </div>
    </div>
  )
}
