/**
 * The workspace browser's viewing store: the session-list grouping mode,
 * persisted across reloads. Module level exports the factory only (a
 * module-level handle would pin the store identity across plugin reloads);
 * register() receives the factory and the browser derives its PropsStore
 * share from the return type.
 */
import { defineStore, type EngineStoreHandle } from '@deepseek-ai/dsh-client-store'
import type { SessionListState } from '@deepseek-ai/dsh-api-session-controller/client'
import type { SessionId } from '@deepseek-ai/dsh-session/types'
import { reconcileManualOrder, type ArchivedFilter, type SessionRowState } from './tree.ts'
import { addExtraFolderTo, promotePrimaryIn, removeExtraFolderFrom } from './folder-transition.ts'
import {
  assignWorkspace, createSection, createSectionsState, deleteSection, moveSection, normalizeSections,
  renameSection, type SectionsState,
} from './sections/model.ts'

/** Browser-local order account for the hierarchy-free flat Session list. */
export const FLAT_SESSION_ORDER_KEY = '__flat_session_order__'

/** Session-list grouping mode: sibling Workspace sections, a Workspace tree, or one flat list. */
export type SessionGroupBy = 'workspace' | 'workspace-tree' | 'flat'
/** Session order: saved manual positions or current recency. */
export type SessionOrderBy = 'manual' | 'updated'

/** Workspace UI viewing state persisted across surface remounts and reloads. */
type WorkspaceViewState = {
  groupBy: SessionGroupBy
  orderBy: SessionOrderBy
  /** Explicit group expansion keyed by Workspace identity, including descendants in tree mode. */
  groupExpansion: Record<string, boolean>
  /** Saved manual order per Workspace group plus the browser-local flat-list account. */
  sessionOrderByAccount: Record<string, string[]>
  /** Archived-row visibility; omitted in pre-filter v5 snapshots and read as 'default'. */
  archivedFilter?: ArchivedFilter
  /** Workspace ids kept at the front of the grouped list, in pin order. */
  pinnedWorkspaceIds: string[]
  /**
   * Unused since the Workspaces section node was removed. Kept so v5 snapshots
   * still rehydrate; the grouped tree always shows Workspace rows.
   */
  workspacesOpen: boolean
  /** Whether the Recent sessions section is expanded. */
  recentsOpen: boolean
  /**
   * Extra source folders per Workspace, owned by this plugin: the shipped host
   * has no folder APIs, so the browser keeps them itself and attributes
   * Sessions to a Workspace by matching their cwd against this list.
   */
  extraFoldersByWorkspace: Record<string, string[]>
  /**
   * Primary directory chosen in the project editor when it is not the host
   * Workspace path. Absent means the host path stays primary.
   */
  primaryByWorkspace?: Record<string, string>
  /** Optional workspace-section layout (Codex-style). Off keeps the original grouped tree. */
  sectionsEnabled?: boolean
  /** Custom and built-in sections; absent in pre-section snapshots and read as the default pair. */
  sections?: SectionsState
  /** Optional compact panel navigation above the Workspace list; off by default. */
  panelNavEnabled?: boolean
  /** User order of `sidebar.panellist` entry ids. */
  panelOrder?: string[]
  /** Panel ids pinned above the "more" accordion; absent means none pinned. */
  panelPinned?: string[]
  /** Section collapse state, keyed by section id. */
  sectionExpansion?: Record<string, boolean>
}

type SessionOrderSource = {
  members: Readonly<Record<string, readonly SessionId[]>>
  summaries: SessionListState['byId']
  rowState: Pick<SessionRowState, 'pinnedSessionIds' | 'archivedSessionIds'>
}

/**
 * Annotation twin of the actions literal below (the export needs a declared
 * return type); drift fails assignability at the defineStore call.
 */
type WorkspaceViewActions = {
  setGroupBy: (draft: WorkspaceViewState, mode: SessionGroupBy) => void
  setOrderBy: (
    draft: WorkspaceViewState,
    mode: SessionOrderBy,
    initialOrders: Readonly<Record<string, readonly string[]>>,
  ) => void
  setGroupExpanded: (draft: WorkspaceViewState, key: string, expanded: boolean) => void
  retainAccountKeys: (draft: WorkspaceViewState, workspaceKeys: readonly string[]) => void
  syncSessionOrders: (
    draft: WorkspaceViewState,
    orders: Readonly<Record<string, readonly string[]>>,
  ) => void
  setSessionOrder: (
    draft: WorkspaceViewState,
    accountKey: string,
    order: readonly string[],
    initialOrders: Readonly<Record<string, readonly string[]>>,
  ) => void
  pinSessionOrder: (
    draft: WorkspaceViewState,
    sessionId: string,
    accountKeys: readonly string[],
    source: SessionOrderSource,
  ) => void
  setArchivedFilter: (draft: WorkspaceViewState, filter: ArchivedFilter) => void
  pinWorkspace: (draft: WorkspaceViewState, workspaceId: string) => void
  unpinWorkspace: (draft: WorkspaceViewState, workspaceId: string) => void
  setWorkspacesOpen: (draft: WorkspaceViewState, open: boolean) => void
  setRecentsOpen: (draft: WorkspaceViewState, open: boolean) => void
  /** Register one extra source folder for a Workspace (plugin-owned). */
  addExtraFolder: (draft: WorkspaceViewState, workspaceId: string, path: string) => void
  /** Drop one extra source folder. */
  removeExtraFolder: (draft: WorkspaceViewState, workspaceId: string, path: string) => void
  /**
   * Promote `path` to the plugin-owned primary. `hostPath` is the directory the
   * host still has registered; it becomes an extra folder while it is not primary.
   */
  promotePrimary: (draft: WorkspaceViewState, workspaceId: string, path: string, hostPath: string) => void
  /** Replace the plugin folder layer with the merged home-file result. */
  installFolderLayer: (
    draft: WorkspaceViewState,
    layer: {
      extraFoldersByWorkspace: Record<string, string[]>
      primaryByWorkspace: Record<string, string>
      sectionsEnabled?: boolean
      sections?: SectionsState
    },
  ) => void
  /** Turn the optional section layout on or off without discarding its structure. */
  setSectionsEnabled: (draft: WorkspaceViewState, enabled: boolean) => void
  /** Put one Workspace into a section (and keep the pin set consistent). */
  assignWorkspaceSection: (draft: WorkspaceViewState, workspaceId: string, sectionId: string) => void
  /** Create a custom section before the fallback "projects" section. */
  createWorkspaceSection: (draft: WorkspaceViewState, sectionId: string, name: string) => void
  renameWorkspaceSection: (draft: WorkspaceViewState, sectionId: string, name: string) => void
  deleteWorkspaceSection: (draft: WorkspaceViewState, sectionId: string) => void
  moveWorkspaceSection: (draft: WorkspaceViewState, sectionId: string, beforeSectionId: string | null) => void
  setSectionExpanded: (draft: WorkspaceViewState, sectionId: string, expanded: boolean) => void
  /** Show or hide the compact panel navigation. */
  setPanelNavEnabled: (draft: WorkspaceViewState, enabled: boolean) => void
  /** Persist a new panel order after an in-place drag. */
  setPanelOrder: (draft: WorkspaceViewState, order: readonly string[]) => void
  /** Persist which panels stay visible outside the "more" accordion. */
  setPanelPinned: (draft: WorkspaceViewState, pinned: readonly string[]) => void
}

/** Copy read-only projections into the persisted mutable store representation. */
function copySessionOrders(
  orders: Readonly<Record<string, readonly string[]>>,
): Record<string, string[]> {
  return Object.fromEntries(Object.entries(orders).map(([key, order]) => [key, [...order]]))
}

/** Copy a read-only extra-folder map into the draft's mutable representation. */
function mutableFolders(map: Readonly<Record<string, readonly string[]>>): Record<string, string[]> {
  return Object.fromEntries(Object.entries(map).map(([key, folders]) => [key, [...folders]]))
}

/** Current section structure, tolerating snapshots written before sections existed. */
function currentSections(draft: WorkspaceViewState): SectionsState {
  return draft.sections ?? createSectionsState()
}

/**
 * Create the workspace browser viewing store handle.
 * @returns the store handle (spec + type + identity + factory in one).
 */
export function createWorkspaceViewStore(): EngineStoreHandle<WorkspaceViewState, WorkspaceViewActions> {
  return defineStore({
    init: (): WorkspaceViewState => ({
      groupBy: 'workspace',
      orderBy: 'updated',
      groupExpansion: {},
      sessionOrderByAccount: {},
      archivedFilter: 'default',
      pinnedWorkspaceIds: [],
      workspacesOpen: true,
      recentsOpen: true,
      extraFoldersByWorkspace: {},
      primaryByWorkspace: {},
      sectionsEnabled: undefined,
      sections: undefined,
      sectionExpansion: {},
    }),
    persist: 'dsh.workspace.view.v5',
    actions: {
      setGroupBy: (d, mode: SessionGroupBy) => { d.groupBy = mode },
      setOrderBy: (d, mode: SessionOrderBy, initialOrders) => {
        if (mode === d.orderBy) return
        d.sessionOrderByAccount = mode === 'manual' ? copySessionOrders(initialOrders) : {}
        d.orderBy = mode
      },
      setGroupExpanded: (d, key: string, expanded: boolean) => { d.groupExpansion[key] = expanded },
      retainAccountKeys: (d, workspaceKeys: readonly string[]) => {
        const retained = new Set(workspaceKeys)
        d.groupExpansion = Object.fromEntries(
          Object.entries(d.groupExpansion).filter(([key]) => retained.has(key)),
        )
        d.sessionOrderByAccount = Object.fromEntries(
          Object.entries(d.sessionOrderByAccount).filter(([key]) => retained.has(key)),
        )
        delete (d as WorkspaceViewState & { sessionUpdatedAtByAccount?: unknown }).sessionUpdatedAtByAccount
        const pinned = Array.isArray(d.pinnedWorkspaceIds) ? d.pinnedWorkspaceIds : []
        d.pinnedWorkspaceIds = pinned.filter(id => retained.has(id))
        if (d.sections) d.sections = normalizeSections(d.sections, workspaceKeys)
        if (typeof d.workspacesOpen !== 'boolean') d.workspacesOpen = true
        if (typeof d.recentsOpen !== 'boolean') d.recentsOpen = true
        // Pre-folder snapshots carry neither map; read them as empty rather than
        // migrating or dropping the rest of the viewing state. Keep the caller's
        // object identity when nothing is pruned: a retain pass must not look
        // like a state change to store subscribers.
        const extra = d.extraFoldersByWorkspace ?? {}
        const extraRetained = Object.entries(extra).filter(([key]) => retained.has(key))
        if (extraRetained.length !== Object.keys(extra).length) d.extraFoldersByWorkspace = Object.fromEntries(extraRetained)
        else d.extraFoldersByWorkspace = extra
        const primary = d.primaryByWorkspace ?? {}
        const primaryRetained = Object.entries(primary).filter(([key]) => retained.has(key))
        if (primaryRetained.length !== Object.keys(primary).length) d.primaryByWorkspace = Object.fromEntries(primaryRetained)
        else d.primaryByWorkspace = primary
      },
      syncSessionOrders: (d, orders) => {
        if (d.orderBy !== 'manual') return
        Object.assign(d.sessionOrderByAccount, copySessionOrders(orders))
      },
      setSessionOrder: (d, accountKey, order, initialOrders) => {
        if (d.orderBy === 'updated') d.sessionOrderByAccount = copySessionOrders(initialOrders)
        else Object.assign(d.sessionOrderByAccount, copySessionOrders(initialOrders))
        d.orderBy = 'manual'
        d.sessionOrderByAccount[accountKey] = [...order]
      },
      pinSessionOrder: (d, sessionId, accountKeys, source) => {
        const selected = new Set(accountKeys)
        d.sessionOrderByAccount = Object.fromEntries(Object.entries(source.members).map(([key, members]) => {
          const order = reconcileManualOrder(members, d.sessionOrderByAccount[key], source.summaries, source.rowState)
          return [key, selected.has(key) ? [sessionId, ...order.filter(id => id !== sessionId)] : order]
        }))
      },
      setArchivedFilter: (d, filter: ArchivedFilter) => { d.archivedFilter = filter },
      pinWorkspace: (d, workspaceId: string) => {
        const pinned = Array.isArray(d.pinnedWorkspaceIds) ? d.pinnedWorkspaceIds : []
        if (pinned.includes(workspaceId)) return
        d.pinnedWorkspaceIds = [...pinned, workspaceId]
      },
      unpinWorkspace: (d, workspaceId: string) => {
        const pinned = Array.isArray(d.pinnedWorkspaceIds) ? d.pinnedWorkspaceIds : []
        d.pinnedWorkspaceIds = pinned.filter(id => id !== workspaceId)
      },
      setWorkspacesOpen: (d, open: boolean) => { d.workspacesOpen = open },
      setRecentsOpen: (d, open: boolean) => { d.recentsOpen = open },
      addExtraFolder: (d, workspaceId: string, path: string) => {
        const folders = addExtraFolderTo(d, workspaceId, path)
        if (folders === d.extraFoldersByWorkspace) return
        d.extraFoldersByWorkspace = mutableFolders(folders)
      },
      removeExtraFolder: (d, workspaceId: string, path: string) => {
        d.extraFoldersByWorkspace = mutableFolders(removeExtraFolderFrom(d, workspaceId, path))
      },
      promotePrimary: (d, workspaceId: string, path: string, hostPath: string) => {
        const next = promotePrimaryIn(d, workspaceId, path, hostPath)
        if (next.extraFoldersByWorkspace === d.extraFoldersByWorkspace
          && next.primaryByWorkspace === d.primaryByWorkspace) return
        d.extraFoldersByWorkspace = mutableFolders(next.extraFoldersByWorkspace)
        d.primaryByWorkspace = { ...next.primaryByWorkspace }
      },
      setSectionsEnabled: (d, enabled: boolean) => {
        d.sectionsEnabled = enabled
        if (!d.sections) d.sections = createSectionsState()
      },
      assignWorkspaceSection: (d, workspaceId: string, sectionId: string) => {
        const next = assignWorkspace(currentSections(d), workspaceId, sectionId)
        if (next === d.sections) return
        d.sections = normalizeSections(next)
        if (sectionId === 'pinned') {
          const pinned = Array.isArray(d.pinnedWorkspaceIds) ? d.pinnedWorkspaceIds : []
          if (!pinned.includes(workspaceId)) d.pinnedWorkspaceIds = [...pinned, workspaceId]
        } else {
          d.pinnedWorkspaceIds = (Array.isArray(d.pinnedWorkspaceIds) ? d.pinnedWorkspaceIds : [])
            .filter(id => id !== workspaceId)
        }
      },
      createWorkspaceSection: (d, sectionId: string, name: string) => {
        d.sections = normalizeSections(createSection(currentSections(d), sectionId, name))
      },
      renameWorkspaceSection: (d, sectionId: string, name: string) => {
        const next = renameSection(currentSections(d), sectionId, name)
        if (next !== d.sections) d.sections = next
      },
      deleteWorkspaceSection: (d, sectionId: string) => {
        const next = deleteSection(currentSections(d), sectionId)
        if (next !== d.sections) d.sections = next
      },
      moveWorkspaceSection: (d, sectionId: string, beforeSectionId: string | null) => {
        const next = moveSection(currentSections(d), sectionId, beforeSectionId)
        if (next !== d.sections) d.sections = next
      },
      setSectionExpanded: (d, sectionId: string, expanded: boolean) => {
        d.sectionExpansion = { ...(d.sectionExpansion ?? {}), [sectionId]: expanded }
      },
      setPanelNavEnabled: (d, enabled: boolean) => {
        d.panelNavEnabled = enabled
      },
      setPanelOrder: (d, order: readonly string[]) => {
        d.panelOrder = [...new Set(order)]
      },
      setPanelPinned: (d, pinned: readonly string[]) => {
        d.panelPinned = [...new Set(pinned)]
      },
      installFolderLayer: (d, layer) => {
        d.extraFoldersByWorkspace = layer.extraFoldersByWorkspace
        d.primaryByWorkspace = layer.primaryByWorkspace
        if (layer.sectionsEnabled !== undefined) d.sectionsEnabled = layer.sectionsEnabled
        if (layer.sections !== undefined) d.sections = normalizeSections(layer.sections)
      },
    },
  })
}

/** The bound write set of one viewing-store instance (what the UiWorkspace service drives). */
export type WorkspaceViewStoreActions = ReturnType<ReturnType<typeof createWorkspaceViewStore>['create']>['actions']
